<template><section class="entity-catalog"><div class="catalog-toolbar"><input v-model="search" type="search" :placeholder="en?'Creature name or ID':'搜索生物名称或 ID'"><label><input v-model="technical" type="checkbox">{{en?'Include technical entities':'包含弹射物等技术实体'}}</label></div><p class="catalog-count">{{shown.length}} {{en?'entities':'种实体'}} · {{en?'Base attributes exclude equipment bonuses.':'基础属性不包含装备附加值。'}}</p><article v-for="e in shown" :key="e.id" class="entity-entry"><h3>{{nameOf(e,lang)}}</h3><code>{{e.id}}</code><dl><template v-for="(value,key) in e.attributes||{}" :key="key"><dt>{{attributeName(key)}}</dt><dd>{{value}}</dd></template></dl><div v-if="Object.keys(e.equipment||{}).length" class="equipment-list"><span>{{en?'Default equipment':'默认装备'}}</span><McItem v-for="(stack,slot) in e.equipment" :key="slot" :id="stack.id" :stack="stack" :show-name="true"/></div><small v-if="e.lootTable">{{en?'Loot table':'战利品表'}}：<code>{{e.lootTable}}</code></small></article></section></template>
<script setup lang="ts">
import{ref,computed,onMounted}from'vue';import{useData}from'vitepress';import{getData,nameOf}from'../lib/wiki';import McItem from'./McItem.vue';const{lang}=useData();const en=computed(()=>lang.value.startsWith('en'));const search=ref(''),technical=ref(false),all=ref<any[]>([]),translations=ref<any>({});const shown=computed(()=>all.value.filter(e=>(technical.value||e.attributes)&&[e.id,e.nameZh,e.nameEn].join(' ').toLocaleLowerCase().includes(search.value.toLocaleLowerCase())).sort((a,b)=>nameOf(a,lang.value).localeCompare(nameOf(b,lang.value),lang.value)));function attributeName(id:string){return translations.value['attribute.name.'+id.split(':')[1]]??id.split(':')[1]};onMounted(async()=>{const[c,l]=await Promise.all([getData(),getData(en.value?'lang-en':'lang-zh')]);all.value=c.entities;translations.value=l});
</script>
